// Love page - minimal functions
(function($) {
  // Flowtime navigation callback (expected by all.min.js)
  window.player = {
    // player.nojavascript is checked by Flowtime
    nojavascript: function() { $('.nojavascript').hide(); }
  };
  window.onNavigation = function() {};

  // Music play/pause toggle
  var audio = document.getElementById('bgmMusic');

  // Click to play (bypasses autoplay policy)
  document.addEventListener('click', function() {
    if (audio && audio.paused) {
      audio.play().catch(function() {});
    }
  }, { once: true });

  // Toggle buttons
  $('#on').click(function() {
    audio.pause();
    $(this).hide();
    $('#off').show();
  });
  $('#off').click(function() {
    audio.play();
    $(this).hide();
    $('#on').show();
  });

  // Progress bar
  if (audio) {
    audio.addEventListener('timeupdate', function() {
      var pct = (audio.currentTime / audio.duration) * 100 || 0;
      $('.progress').css('width', pct + '%');
    });
  }

  // Hide loading text
  $('.nojavascript').hide();

})(jQuery);
